import{_ as l,a0 as o,w as p,s as d,ao as e,I as s,a1 as a,A as r,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"5 個免費的 Linux 分區管理器 | LCTT x X-CMD","titleTemplate":false,"description":"5 個免費的 Linux 分區管理器 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 個免費的 Linux 分區管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 個免費的 Linux 分區管理器 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190801 5 Free Partition Managers for Linux","title":"5 個免費的 Linux 分區管理器","tag":"201908","desc":""},"relativePath":"201908/20190801 5 Free Partition Managers for Linux.md","filePath":"[post].md"}'),u={name:"201908/20190801 5 Free Partition Managers for Linux.md"};function g(f,t,k,m,x,b){const n=o("Link");return p(),d("div",null,[t[29]||(t[29]=e('<h1 id="_5-個免費的-linux-分區管理器" tabindex="-1">5 個免費的 Linux 分區管理器 <a class="header-anchor" href="#_5-個免費的-linux-分區管理器" aria-label="Permalink to “5 個免費的 Linux 分區管理器”">​</a></h1><blockquote><p>以下是我們推薦的 Linux 分區工具。它們能讓你刪除、添加、調整或縮放 Linux 系統上的磁盤分區。</p></blockquote><p>通常，你在安裝操作系統時決定磁盤分區。但是，如果你需要在安裝後的某個時間修改分區，該怎麼辦？你無法回到系統安裝階段。因此，這就需要分區管理器（或準確地説是磁盤分區管理器）上場了。</p><p>在大多數情況下，你無需單獨安裝分區管理器，因為它已預先安裝。此外，值得注意的是，你可以選擇基於命令列或有 GUI 的分區管理器。</p><p><strong>注意！</strong></p><blockquote><p>磁盤分區是一項有風險的任務。除非絕對必要，否則不要這樣做。</p><p>如果你使用的是基於命令列的分區工具，那麼需要學習完成任務的命令。否則，你可能最終會擦除整個磁盤。</p></blockquote><h3 id="linux-中的-5-個管理磁盤分區的工具" tabindex="-1">Linux 中的 5 個管理磁盤分區的工具 <a class="header-anchor" href="#linux-中的-5-個管理磁盤分區的工具" aria-label="Permalink to “Linux 中的 5 個管理磁盤分區的工具”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/07/disk-partitioning-tools-linux.jpg?resize=800%2C450&amp;ssl=1" alt=""></p><p>下面的列表沒有特定的排名順序。大多數分區工具應該存在於 Linux 發行版的倉庫中。</p><h4 id="gparted" tabindex="-1">GParted <a class="header-anchor" href="#gparted" aria-label="Permalink to “GParted”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/07/g-parted.png?ssl=1" alt="GParted"></p><p>這可能是 Linux 發行版中最流行的基於 GUI 的分區管理器。你可能已在某些發行版中預裝它。如果還沒有，只需在軟件中心搜索它即可完成安裝。</p><p>它會在啓動時直接提示你以 root 用户進行身份驗證。所以，你根本不需要在這裏使用終端。身份驗證後，它會分析設備，然後讓你調整磁盤分區。如果發生數據丟失或意外刪除文件，你還可以找到“嘗試數據救援”的選項。</p>',13)),s("ul",null,[s("li",null,[a(n,{href:"https://gparted.org/"},{default:r(()=>[...t[0]||(t[0]=[i("GParted",-1)])]),_:1})])]),t[30]||(t[30]=s("h4",{id:"gnome-disks",tabindex:"-1"},[i("GNOME Disks "),s("a",{class:"header-anchor",href:"#gnome-disks","aria-label":"Permalink to “GNOME Disks”"},"​")],-1)),t[31]||(t[31]=s("p",null,[s("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/07/gnome-disks.png?ssl=1",alt:"Gnome Disks"})],-1)),t[32]||(t[32]=s("p",null,"一個基於 GUI 的分區管理器，隨 Ubuntu 或任何基於 Ubuntu 的發行版（如 Zorin OS）一起出現。",-1)),s("p",null,[t[2]||(t[2]=i("它能讓你刪除、添加、縮放和微調分區。如果你遇到故障，它甚至可以",-1)),a(n,{href:"https://itsfoss.com/format-usb-drive-sd-card-ubuntu/"},{default:r(()=>[...t[1]||(t[1]=[i("在 Ubuntu 中格式化 USB",-1)])]),_:1}),t[3]||(t[3]=i(" 來幫助你救援機器。",-1))]),t[33]||(t[33]=s("p",null,"你甚至可以藉助此工具嘗試修復分區。它的選項還包括編輯文件系統、創建分區鏡像、還原鏡像以及對分區進行基準測試。",-1)),s("ul",null,[s("li",null,[a(n,{href:"https://wiki.gnome.org/Apps/Disks"},{default:r(()=>[...t[4]||(t[4]=[i("GNOME Disks",-1)])]),_:1})])]),t[34]||(t[34]=e('<h4 id="kde-partition-manager" tabindex="-1">KDE Partition Manager <a class="header-anchor" href="#kde-partition-manager" aria-label="Permalink to “KDE Partition Manager”">​</a></h4><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/07/kde-partition-manager.jpg?resize=800%2C404&amp;ssl=1" alt="Kde Partition Manager"></p><p>KDE Partition Manager 應該已經預裝在基於 KDE 的 Linux 發行版上了。但是，如果沒有，你可以在軟件中心搜索並輕鬆安裝它。</p><p>如果你不是預裝的，那麼可能會在嘗試啓動時通知你沒有管理權限。沒有管理員權限，你無法做任何事情。因此，在這種情況下，請輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo partitionmanager</span></span></code></pre></div><p>它將掃描你的設備，然後你就可以創建、移動、複製、刪除和縮放分區。你還可以導入/導出分區表及使用其他許多調整選項。</p>',6)),s("ul",null,[s("li",null,[a(n,{href:"https://kde.org/applications/system/org.kde.partitionmanager"},{default:r(()=>[...t[5]||(t[5]=[i("KDE Partition Manager",-1)])]),_:1})])]),t[35]||(t[35]=s("h4",{id:"fdisk-命令列",tabindex:"-1"},[i("Fdisk（命令列） "),s("a",{class:"header-anchor",href:"#fdisk-命令列","aria-label":"Permalink to “Fdisk（命令列）”"},"​")],-1)),t[36]||(t[36]=s("p",null,[s("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/07/fdisk.jpg?fit=800%2C496&ssl=1",alt:"Fdisk"})],-1)),s("p",null,[a(n,{href:"https://en.wikipedia.org/wiki/Fdisk"},{default:r(()=>[...t[6]||(t[6]=[i("fdisk",-1)])]),_:1}),t[7]||(t[7]=i(" 是一個命令列程序，它在每個類 Unix 的系統中都有。不要擔心，即使它需要你啓動終端並輸入命令，但這並不是很困難。但是，如果你在使用基於文本的程序時感到困惑，那麼你應該繼續使用上面提到的 GUI 程序。它們都做同樣的事情。",-1))]),t[37]||(t[37]=e('<p>要啓動 <code>fdisk</code>，你必須是 root 用户並指定管理分區的設備。以下是該命令的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fdisk /dev/sdc</span></span></code></pre></div>',2)),s("p",null,[t[9]||(t[9]=i("你可以參考 ",-1)),a(n,{href:"https://www.tldp.org/HOWTO/Partition/fdisk_partitioning.html"},{default:r(()=>[...t[8]||(t[8]=[i("Linux 文檔項目的維基頁面",-1)])]),_:1}),t[10]||(t[10]=i("以獲取命令列表以及有關其工作原理的更多詳細信息。",-1))]),t[38]||(t[38]=e('<h4 id="gnu-parted-命令列" tabindex="-1">GNU Parted（命令列） <a class="header-anchor" href="#gnu-parted-命令列" aria-label="Permalink to “GNU Parted（命令列）”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/07/gnu-parted.png?fit=800%2C559&amp;ssl=1" alt="Gnu Parted"></p><p>這是在你 Linux 發行版上預安裝的另一個命令列程序。你需要輸入下面的命令啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo parted</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>',5)),s("p",null,[t[12]||(t[12]=i("我不會忘了説 ",-1)),a(n,{href:"http://qtparted.sourceforge.net/"},{default:r(()=>[...t[11]||(t[11]=[i("QtParted",-1)])]),_:1}),t[13]||(t[13]=i(" 是分區管理器的替代品之一。但它已經幾年沒有維護，因此我不建議使用它。",-1))]),t[39]||(t[39]=s("p",null,"你如何看待這裏提到的分區管理器？我有錯過你最喜歡的嗎？讓我知道，我將根據你的建議更新這個 Linux 分區管理器列表。",-1)),t[40]||(t[40]=s("hr",null,null,-1)),s("p",null,[t[15]||(t[15]=i("via: ",-1)),a(n,{href:"https://itsfoss.com/partition-managers-linux/"},{default:r(()=>[...t[14]||(t[14]=[i("https://itsfoss.com/partition-managers-linux/",-1)])]),_:1})]),s("p",null,[t[20]||(t[20]=i("作者：",-1)),a(n,{href:"https://itsfoss.com/author/ankush/"},{default:r(()=>[...t[16]||(t[16]=[i("Ankush Das",-1)])]),_:1}),t[21]||(t[21]=i(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[17]||(t[17]=[i("lujun9972",-1)])]),_:1}),t[22]||(t[22]=i(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:r(()=>[...t[18]||(t[18]=[i("geekpi",-1)])]),_:1}),t[23]||(t[23]=i(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[19]||(t[19]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[26]||(t[26]=i("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[24]||(t[24]=[i("LCTT",-1)])]),_:1}),t[27]||(t[27]=i(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:r(()=>[...t[25]||(t[25]=[i("Linux中國",-1)])]),_:1}),t[28]||(t[28]=i(" 榮譽推出",-1))])])}const C=l(u,[["render",g]]);export{P as __pageData,C as default};
